def blade_edge_floor_height(obj,rotation,edge,table_z):
    if obj['source_asset']['sha256']!=SOURCE_SHA or not np.allclose(obj['size'],HALF_SIZE,atol=1e-9,rtol=0):
        raise ValueError('Spatula clearance requires exact reviewed source dimensions')
    r=np.asarray(rotation,float);edge=np.asarray(edge,float)
    if r.shape!=(3,3) or edge.shape!=(3,) or not np.isfinite(r).all():raise ValueError('Invalid measured tool frame')
    relative=(SUPPORT_VERTICES-edge)@r.T
    return float(table_z-relative[:,2].min()+.0002)
